index ea53014..3beb668 100644
--- a/src/invoice.mjs
+++ b/src/invoice.mjs
@@ -1,10 +1,11 @@
 import { priceOrder } from "./pricing.mjs";

-export function renderInvoice(order) {
-  const priced = priceOrder(order);
+export function renderInvoice(order, options) {
+  const priced = priceOrder(order, options);
   return {
     id: order.id,
     subtotal_cents: priced.subtotal,
+    discount_cents: priced.discount,
     total_cents: priced.total,
   };
 }
diff --git a/src/pricing.mjs b/src/pricing.mjs
index 6882f07..a0269a3 100644
--- a/src/pricing.mjs
+++ b/src/pricing.mjs
@@ -1,6 +1,7 @@
 import { orderSubtotal } from "./order.mjs";

-export function priceOrder(order) {
+export function priceOrder(order, { discountPercent = 0 } = {}) {
   const subtotal = orderSubtotal(order);
-  return { subtotal, total: subtotal };
+  const discount = Math.ceil(subtotal * discountPercent / 100);
+  return { subtotal, discount, total: subtotal - discount };
 }

